use std::fs

fn main() {
    let limit: int = 200000
    let mut sieve: Vec<bool> = []
    let mut counts: Vec<int> = []
    let mut largest: Vec<int> = []
    for i in 0..(limit + 1) {
        sieve.push(true)
        counts.push(0)
        largest.push(0)
    }
    let mut i: int = 2
    while i <= limit {
        if sieve[i] {
            let mut j: int = i * i
            while j <= limit {
                sieve[j] = false
                j = j + i
            }
        }
        i += 1
    }
    let mut c = 0
    let mut last = 0
    for k in 0..(limit + 1) {
        if k >= 2 && sieve[k] {
            c += 1
            last = k as int
        }
        counts[k] = c
        largest[k] = last
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    let mut out = ""
    for line in text.lines() {
        let t = line.trim()
        if t == "" { continue }
        if first {
            first = false
            continue
        }
        let n: int = t.parse().unwrap_or(0)
        if n < 2 {
            out = out + "0 none\n"
        } else {
            out = out + "${counts[n]} ${largest[n]}\n"
        }
    }
    print("${out}")
}

